import json
from collections import Counter
PLAN = json.loads("""{"resource_changes": [
 {"address": "aws_s3_bucket.logs", "change": {"actions": ["no-op"]}},
 {"address": "aws_instance.web[0]", "change": {"actions": ["delete", "create"]}},
 {"address": "aws_db_instance.main", "change": {"actions": ["delete"]}},
 {"address": "aws_security_group.web", "change": {"actions": ["update"]}},
 {"address": "aws_iam_role.ci", "change": {"actions": ["create"]}}
]}""")
def action(a):
    if a == ["delete", "create"] or a == ["create", "delete"]:
        return "replace"
    return a[0]
counts = Counter()
danger = []
for rc in PLAN["resource_changes"]:
    act = action(rc["change"]["actions"])
    counts[act] += 1
    if act in ("delete", "replace"):
        danger.append((rc["address"], act))
print(dict(sorted(counts.items())))
for addr, act in sorted(danger):
    print("REVIEW", act, addr)
